import{_ as t,o as a,c as i,ah as r}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"March 24, 2026: The Power Castling – Upper Austria Keeps Its Distance","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/2026-03-24-die-rochade-der-macht.md","filePath":"en/logbuch/2026-03-24-die-rochade-der-macht.md"}'),n={name:"en/logbuch/2026-03-24-die-rochade-der-macht.md"};function o(s,e,h,l,c,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="march-24-2026-the-power-castling-–-upper-austria-keeps-its-distance" tabindex="-1">March 24, 2026: The Power Castling – Upper Austria Keeps Its Distance <a class="header-anchor" href="#march-24-2026-the-power-castling-–-upper-austria-keeps-its-distance" aria-label="Permalink to &quot;March 24, 2026: The Power Castling – Upper Austria Keeps Its Distance&quot;">​</a></h1><p>Today, on Tuesday, evidence is mounting that the Upper Austrian People&#39;s Party (OÖVP) intends to end the Wöginger era at the state level in an orderly fashion. While August Wöginger continues to fight allegations of incitement to abuse of office at the Linz Regional Court, the strategic decision has been made: <strong>Wolfgang Hattmannsdorfer</strong> will take over his role in the state leadership.</p><h2 id="forensic-analysis-of-the-situation" tabindex="-1">Forensic Analysis of the Situation: <a class="header-anchor" href="#forensic-analysis-of-the-situation" aria-label="Permalink to &quot;Forensic Analysis of the Situation:&quot;">​</a></h2><ol><li><strong>The Stelzer Distance:</strong> Governor Thomas Stelzer is performing a classic political castling maneuver. By nominating Hattmannsdorfer as his deputy, he is creating a personal firewall between the state party and the ongoing trial against Wöginger. The aim is to appear &quot;clean&quot; at the state party conference (April 24) – just three days after the expected verdict.</li><li><strong>Wöginger&#39;s Federal Fortress:</strong> Interestingly, Wöginger shows no signs of withdrawal at the federal level. He is iron-fistedly maintaining his role as parliamentary party leader in the National Council. The strategy seems clear: sacrifice the state to hold the federal level (and the &quot;Hard Prose&quot; there).</li><li><strong>Hattmannsdorfer as Profiteer:</strong> The Minister of Economic Affairs is consolidating his reputation as the &quot;crown prince.&quot; He is moving into the deputy team and will become the most important link between Vienna and Linz. In our archives, we now list him as the &quot;Strong Man of the Future.&quot;</li></ol><h2 id="the-mood-in-the-archive" tabindex="-1">The Mood in the Archive: <a class="header-anchor" href="#the-mood-in-the-archive" aria-label="Permalink to &quot;The Mood in the Archive:&quot;">​</a></h2><p>Our traffic figures show that the public sees through the separation of state and federal functions as a tactical maneuver. The virality index is stabilizing at a high level, while the forensics unit checks for new cross-connections between Hattmannsdorfer&#39;s rise and the WKO (Chamber of Commerce) networks.</p><hr><p><em>Tomorrow: A deeper look into the WKO networks of the new crown prince.</em></p>',8)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
